lid:=(p->>'legacy_id')::int; cd:=p->>'codigo'; ver:=(p->>'version')::int;
IF NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=ver AND estado='PUBLICADA' AND hash=p->>'hash') THEN RAISE EXCEPTION 'BRIDGE_HASH_DRIFT %',cd; END IF;
h:=lf_ops.nucleo_hash_paquete_v1(cd,ver);
IF h IS DISTINCT FROM p->>'paquete' THEN RAISE EXCEPTION 'BRIDGE_PACKAGE_DRIFT %',cd; END IF;
IF EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid) THEN
IF EXISTS(SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada WHERE legacy_id=lid AND nucleo_codigo=cd AND version_nucleo=ver) AND NOT (lid=235 AND cd='S9-C24' AND EXISTS(SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada WHERE legacy_id=lid AND nucleo_codigo=cd AND version_nucleo=ver AND estado_cobertura='PARCIAL')) THEN RAISE EXCEPTION 'BRIDGE_DUPLICATE % %',lid,cd; END IF;
SELECT descripcion INTO old_desc FROM lf_ops.reglas WHERE id=lid;
SELECT descripcion INTO new_desc FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=ver;
IF lid=235 AND cd='S9-C24' AND EXISTS(SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada WHERE legacy_id=lid AND nucleo_codigo=cd AND version_nucleo=ver AND estado_cobertura='PARCIAL') THEN
UPDATE lf_ops.lf_nucleo_cobertura_legada SET estado_cobertura='REEMPLAZADA',diferencias=p->>'diferencias',evidencia=jsonb_build_object('fuente','lf_ops.reglas/'||lid,'contraste','LEGADA: '||old_desc||' NUCLEO: '||new_desc||' DIFERENCIA: '||(p->>'diferencias'),'residual','','juicio','Claude independiente 2026-11-24 14:52','limite_aceptacion','Cobertura funcional; binding runtime no certificado'),hash_paquete=h,revisado_por='GPT / Claude independiente' WHERE legacy_id=lid AND nucleo_codigo=cd AND version_nucleo=ver;
ELSE
INSERT INTO lf_ops.lf_nucleo_cobertura_legada(legacy_id,nucleo_codigo,version_nucleo,estado_cobertura,diferencias,evidencia,hash_paquete,revisado_por)
VALUES(lid,cd,ver,p->>'estado',p->>'diferencias',jsonb_build_object('fuente','lf_ops.reglas/'||lid,'contraste','LEGADA: '||old_desc||' NUCLEO: '||new_desc||' DIFERENCIA: '||(p->>'diferencias'),'residual',p->>'residual','juicio','Claude independiente 2026-11-24 14:40','limite_aceptacion','Cobertura funcional; binding runtime no certificado'),h,'GPT / Claude puente independiente');
END IF;
n:=n+1;
ELSIF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'BRIDGE_SOURCE_MISSING %',lid; END IF;
END LOOP;
IF ((SELECT count(*) FROM lf_ops.reglas)=586 AND n<>19) OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY id) FROM lf_ops.reglas t) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones t) IS DISTINCT FROM b_dep THEN RAISE EXCEPTION 'BRIDGE_READBACK_FAIL %',n; END IF;
IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'BRIDGE_DPIG03_FAIL'; END IF;
RAISE NOTICE 'BRIDGE_PASS links=% DPIG03=0',n;
END $bridge$;
COMMIT;
